SELECT a.id AS avatar_id, a.type , a.name AS avatar_name, a.price,
CASE WHEN i.avatar_id IS NOT NULL THEN 1 ELSE 0 END AS owned
FROM avatar_tb a
LEFT JOIN inventory_tb i ON a.id = i.avatar_id AND i.user_id = #{userId};
WHERE a.type = 1;

